def gm(a,b):
    p=0
    for _ in range(8):
        if b & 1:
            p ^= a
        hi = a & 0x80
        a = (a << 1) & 0xFF
        if hi:
            a ^= 0x1B
        b >>= 1
    return p

def gp(a,n):
    r=1
    while n:
        if n & 1:
            r = gm(r,a)
        a = gm(a,a)
        n >>= 1
    return r

def sbox(x):
    inv = 0 if x == 0 else gp(x,254)
    b = inv
    for s in (1,2,3,4):
        b ^= ((inv << s) | (inv >> (8-s))) & 0xFF
    return b ^ 0x63

